package br.com.sussmartcare.clinicalquery.infrastructure; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="processed_events") public class ProcessedEvent{@Id private UUID eventId;@Column(nullable=false)private String consumerName;@Column(nullable=false)private Instant processedAt;protected ProcessedEvent(){}public ProcessedEvent(UUID id,String name){eventId=id;consumerName=name;processedAt=Instant.now();}}
